<?php
$error=null;
$keys=['hospital_name','hospital_phone','hospital_address','currency_symbol','appointment_cancellation_hours','queue_refresh_seconds'];
if(request_method('POST')){try{verify_csrf();$submitted=$_POST['settings']??[];if(!is_array($submitted))throw new RuntimeException('Invalid settings payload.');$cancelHours=(int)($submitted['appointment_cancellation_hours']??4);$queueSeconds=(int)($submitted['queue_refresh_seconds']??30);if($cancelHours<0||$cancelHours>168)throw new RuntimeException('Cancellation notice must be between 0 and 168 hours.');if($queueSeconds<10||$queueSeconds>3600)throw new RuntimeException('Queue refresh must be between 10 and 3600 seconds.');foreach($submitted as $key=>$value){if(!is_string($key)||!in_array($key,$keys,true))continue;$clean=trim((string)$value);if($key==='appointment_cancellation_hours')$clean=(string)$cancelHours;if($key==='queue_refresh_seconds')$clean=(string)$queueSeconds;db()->prepare('INSERT INTO system_settings (setting_key,setting_value,description,updated_by) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)')->execute([$key,$clean,ucwords(str_replace('_',' ',$key)),current_user()['user_id']]);}log_action('UPDATE_SETTINGS','system_settings');flash('settings','System settings updated.','success');redirect_to('settings');}catch(Throwable $e){$error=$e->getMessage();}}
$settings=[];$stmt=db()->query('SELECT setting_key,setting_value FROM system_settings');foreach($stmt as $r)$settings[$r['setting_key']]=$r['setting_value'];
?>
<div class="page-header"><div><h2>System settings</h2><p>Hospital identity and basic operational defaults.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="grid grid-3"><div class="card" style="grid-column:span 2"><form method="post"><?=csrf_field()?><div class="form-grid"><div class="field"><label>Hospital name</label><input class="input" name="settings[hospital_name]" value="<?=e($settings['hospital_name']??'')?>"></div><div class="field"><label>Hospital phone</label><input class="input" name="settings[hospital_phone]" value="<?=e($settings['hospital_phone']??'')?>"></div><div class="field" style="grid-column:1/-1"><label>Hospital address</label><textarea class="textarea" name="settings[hospital_address]"><?=e($settings['hospital_address']??'')?></textarea></div><div class="field"><label>Currency symbol</label><input class="input" name="settings[currency_symbol]" value="<?=e($settings['currency_symbol']??'৳')?>"></div><div class="field"><label>Cancellation notice hours</label><input class="input" type="number" min="0" name="settings[appointment_cancellation_hours]" value="<?=e($settings['appointment_cancellation_hours']??'4')?>"></div><div class="field"><label>Queue refresh seconds</label><input class="input" type="number" min="10" name="settings[queue_refresh_seconds]" value="<?=e($settings['queue_refresh_seconds']??'30')?>"></div></div><button class="btn btn-primary">Save settings</button></form></div><div class="card"><h3 class="mt-0">Environment</h3><p><strong>PHP:</strong> <?=e(PHP_VERSION)?></p><p><strong>Database:</strong> <?=e((string)config('db.name'))?></p><p><strong>Timezone:</strong> <?=e((string)config('app.timezone'))?></p><p><strong>Application URL:</strong><br><span class="text-muted"><?=e((string)config('app.base_url'))?></span></p><div class="alert alert-warning"><div><strong>Setup protection</strong><br>Keep <code>storage/setup.lock</code> in place after installation.</div></div></div></div>
